beforeExample:
import java.util.HashMap;
import org.eclipse.swt.widgets.Control;

public class MyClass {
    public void someMethod(Control w, HashMap h, boolean enabled) {
        if (!w.isDisposed()) {
            h.put(w, new Boolean(w.isEnabled()));
            w.setEnabled(enabled);
        }
        boolean result = (new Boolean(true)).booleanValue();
        Boolean myBool = new Boolean(false);
    }

    public boolean isEnabled() { return true; }
}

afterExample:
import java.util.HashMap;
import org.eclipse.swt.widgets.Control;

public class MyClass {
    public void someMethod(Control w, HashMap h, boolean enabled) {
        if (!w.isDisposed()) {
            h.put(w, Boolean.valueOf(w.isEnabled()));
            w.setEnabled(enabled);
        }
        boolean result = (Boolean.valueOf(true)).booleanValue();
        Boolean myBool = Boolean.valueOf(false);
    }

    public boolean isEnabled() { return true; }
}

